package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.net.MalformedURLException;
import java.net.URL;
import java.util.*;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.select.NodeTraversor;
import org.jsoup.select.NodeVisitor;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class Node_hasAttr_TriageGen2Test {

    private Node node;
    private Attributes attributes;

    @Before
    public void setUp() {
        // Since Node is abstract or has protected constructors, 
        // we use an Element (which extends Node) for testing purposes.
        // Alternatively, we can use the Parser to create a real Node instance.
        node = Parser.parseBodyFragment("<div id=\"test\" class=\"container\"></div>").child(0);
        attributes = node.attributes();
    }

    @Test
    public void testHasAttr_WithExistingAttribute() {
        // Test an attribute that exists
        boolean result = node.hasAttr("id");
        Assert.assertTrue("Should return true for existing attribute 'id'", result);

        // Test another existing attribute
        boolean resultClass = node.hasAttr("class");
        Assert.assertTrue("Should return true for existing attribute 'class'", resultClass);
    }

    @Test
    public void testHasAttr_WithNonExistingAttribute() {
        // Test an attribute that does not exist
        boolean result = node.hasAttr("nonExistent");
        Assert.assertFalse("Should return false for non-existent attribute", result);
    }

    @Test
    public void testHasAttr_WithEmptyString() {
        // Test with an empty string key
        boolean result = node.hasAttr("");
        Assert.assertFalse("Should return false for empty string attribute key", result);
    }

    @Test(expected = NullPointerException.class)
    public void testHasAttr_WithNullKey() {
        // Validate.notNull(attributeKey) will throw NullPointerException if null
        node.hasAttr(null);
    }

    @Test
    public void testHasAttr_AfterRemovingAttribute() {
        // Verify state change impacts hasAttr
        String key = "id";
        Assert.assertTrue(node.hasAttr(key));

        node.removeAttr(key);
        Assert.assertFalse("Should return false after attribute is removed", node.hasAttr(key));
    }
}
